style.css:
@-moz-document domain("roblox.com") {
/* Sidebar basic state */
    .left-nav {
        width: 64px !important;
        min-width: 64px !important;
        transition: width 0.15s ease-in-out !important;
        overflow-x: hidden !important;
        white-space: nowrap !important;
        z-index: 1005 !important;
        will-change: width;
    }

    /* Sidebar hover state */
    .left-nav:hover {
        width: 288px !important;
    }

    /* Hide sidebar when it's supposed to be collapsed/invisible */
    .left-nav[class*="invisible"],
    .left-nav[class*="translateX(-100%)"] {
        display: none !important;
        visibility: hidden !important;
        width: 0 !important;
    }

    .left-nav[class*="large:visible"] {
        visibility: inherit !important;
    }

    /* Force inner elements to fill the expanding width */
    .left-nav .width-\[288px\], 
    .left-nav .width-\[289px\], 
    .left-nav .width-\[299px\],
    .left-nav [class*="width-"] {
        width: 100% !important;
        min-width: unset !important;
    }

    /* Logo handling: show only the small 'R' icon */
    .icon-logo, .icon-logo-wordmark { display: none !important; }
    .icon-logo-r { display: inline-block !important; }
    .btn-navigation-nav-menu-md { display: flex !important; visibility: visible !important; }

    /* Navbar alignment fixes */
    .navbar-left, .rbx-navbar-header {
        padding-left: 0 !important;
        margin-left: 5px !important;
    }
    .rbx-navbar-header {
        width: 74px !important;
        padding-right: 0 !important;
        margin-right: 5px !important;
    }
    [data-testid="navigation-search-input"].navbar-left.navbar-search {
        margin-left: 0 !important;
        padding-left: 0 !important;
    }

    /* Hide text and premium labels when sidebar is NOT hovered */
    .left-nav:not(:hover) span:not([class*="icon"]),
    .left-nav:not(:hover) .text-label,
    .left-nav:not(:hover) [class*="premium"], 
    .left-nav:not(:hover) .premium-container,
    .left-nav:not(:hover) a[href*="premium"] { 
        display: none !important; 
    }

    /* Show premium labels on hover */
    .left-nav:hover [class*="premium"], 
    .left-nav:hover .premium-container,
    .left-nav:hover a[href*="premium"] {
        display: flex !important;
        visibility: visible !important;
    }

    /* Center main content and prevent shifting */
    #container-main, 
    .content, 
    .main-content {
        margin-left: auto !important;
        margin-right: auto !important;
        max-width: 1200px !important;
        float: none !important;
        transform: none !important; 
    }

    /* Search bar layout */
    .navbar-left { flex: 0 0 auto !important; }
    .navbar-search, .rbx-navbar-search {
        margin-left: 20px !important;
        flex-grow: 1 !important;
        max-width: 800px !important;
    }
    .navbar-right { margin-left: auto !important; }

    /* Footer centering */
    #footer-container, .container-footer {
        width: 100% !important;
        max-width: 100% !important;
        margin-left: 0 !important;
        text-align: center !important;
    }
}
